import React, { useState } from 'react';
import {Fade, Zoom} from 'react-reveal';

function App () {
  
  const availableLoads = [
    {name: 'Charge a phone for 2 hours', load: 20, duration: 2},
    {name: 'Charge a Laptop for 5 hours', load: 60, duration: 5},
    {name: 'Watch TV (LCD) for 2 hours', load: 60, duration: 2},
    {name: 'Run a Wifi router for 24 hours', load: 10, duration: 24},
    {name: 'Charge camera gear for an hour', load: 25, duration: 1},
    {name: 'Run large speakers for 3 hours', load: 150, duration: 3},
    {name: 'Run a fan for 3 hours', load: 50, duration: 3},
    {name: 'Cook on an induction hot plate for 1 hour', load: 1200, duration: 1},
    {name: 'Run a CPAP Machine overnight', load: 40, duration: 8},
    {name: 'Run a Mini Fridge for 24 hours', load: 80, duration: 24},
    {name: 'Run an Air Conditioner for 2 hours', load: 450, duration: 2},
    {name: 'Back up a Family Fridge for 24 hours', load: 800, duration: 24},
    {name: 'Make 12 cups of coffee with a Coffee Maker for 10 minutes', load: 1200, duration: 0.2},
    {name: 'Curl your hair with a Curling Iron for 10 minutes', load: 1400, duration: 0.2},
    {name: 'Dry your hair with a Hair Dryer for 10 minutes', load: 2000, duration: 0.2},
    {name: 'Run a Clothes Dryer for an hour', load: 3000, duration: 1}
  ]
  const [offgrid, setOffgrid] = useState([])
  const [sametime, setSametime] = useState([])
  const [everyday, setEveryday] = useState([])

  const [activestep, setActivestep] = useState(1)

  function makeTotalWatts(){
    let total = 0
    console.log(sametime)
    sametime.map(device => total += device.load)
    if (total < 0) return 0
    return total
  }

  function makeTotalBatteryUsage(){
    let total = 0
    console.log(everyday)
    everyday.map(device => total += (device.load * device.duration))
    if (total < 0) return '0'
    return total
  }

  return (
  <div className="App" style={{paddingTop: 40}}>

    {activestep === 1 && 
    <div>
      <Fade><h3>Select the devices you want to run off-grid ☀️</h3></Fade>
      <div>
        {availableLoads.map(load => 
        <button 
          className={offgrid.some(off => off.name === load.name) ? "btn btn-primary m-1" : "btn btn-outline-primary m-1"} 
          onClick={() => offgrid.some(off => off.name === load.name) ? setOffgrid(offgrid.filter(data => data.name !== load.name)) : setOffgrid([...offgrid, load])}
          >
          {load.name} {offgrid.some(off => off.name === load.name) ? ' x' : ''}
        </button>
        )}
      </div>
      <br/>
      <button className="btn btn-primary" disabled={offgrid.length === 0} onClick={() => setActivestep(2)}>Next</button>
    </div>}
    
    
    {activestep === 2 && 
    <Fade>
      <div>
        <h3>Which of these devices will you be running <i>at the same time</i>?</h3>
        <p>Note: this will influence the inverter size</p>
          <div>
          {offgrid.map(load => 
          <button 
            className={sametime.some(off => off.name === load.name) ? "btn btn-primary m-1" : "btn btn-outline-primary m-1"} 
            onClick={() => sametime.some(off => off.name === load.name) ? setSametime(sametime.filter(data => data.name !== load.name)) : setSametime([...sametime, load])}
            >
            {load.name} {sametime.some(off => off.name === load.name) ? ' x' : ''}
          </button>
          )}
        </div>
        <hr/>
        <button className="btn btn-primary" disabled={sametime.length === 0} onClick={() => setActivestep(3)}>Next</button>
      </div>
    </Fade>
    }

    
    {activestep === 3 && 
    <Fade>
      <div>
        <h3>Which of these devices will you be running <i>every day</i>?</h3>
        <p>Note: this will influence the battery size</p>
        <div>
          {offgrid.map(load => 
          <button 
            className={everyday.some(off => off.name === load.name) ? "btn btn-primary m-1" : "btn btn-outline-primary m-1"} 
            onClick={() => everyday.some(off => off.name === load.name) ? setEveryday(everyday.filter(data => data.name !== load.name)) : setEveryday([...everyday, load])}
            >
            {load.name} {everyday.some(off => off.name === load.name) ? ' x' : ''}
          </button>
          )}
        </div>
        <hr/>
        <button className="btn btn-primary" disabled={everyday.length === 0} onClick={() => setActivestep(4)}>Next</button>
      </div>
    </Fade>}

    
    {activestep === 4 && 
    <Zoom>
      <div>
        <h3 class="text-primary">Your Results:</h3>
        <h2>We recommend the <a target="_blank" href="/solar-kit-500">Medium Kit</a> for you.</h2>
        <br/>
        <h3 class="text-primary">Why?</h3>
        <h3>Based on your answers you will need at least the following component sizes, which Medium includes built-in.</h3>
        <div className="row">
          <div className="col">
            <div className="card p-3">
              <h3>🔋 Battery Size</h3>
              <p><b>{makeTotalBatteryUsage()}Wh</b> is your recommended Battery size to run all the devices you listed every day. The Medium Kit has a 540Wh battery</p>
              <code>Calculation: {everyday.map((device, i) => <div>{i !== 0 && '+ '}{device.load * device.duration}Wh to {device.name}<br/>&nbsp;&nbsp;&nbsp;({device.load}W * {device.duration}h)</div>)}<div>= {makeTotalBatteryUsage()}Wh</div></code>
            </div>
          </div>
          <div className="col">
            <div className="card p-3">
              <h3>⚡️ Inverter Size</h3>
              <p><b>{ makeTotalWatts()}W</b> is your recommended Inverter size to run the devices told us about at the same time. The Medium Kit has a 500W inverter</p>
              <code>Calculation: {sametime.map((device, i) => <div>{i !== 0 && '+ '}{device.load}W to {device.name}</div>)}<div>= { makeTotalWatts()}W</div></code>
            </div>
          </div>
          <div className="col">
            <div className="card p-3">
              <h3>☀️ Solar Size</h3>
              <p><b>{makeTotalBatteryUsage() / 5}W</b> is your recommended Solar size to recharge the kit's battery from sunshine every day. The Medium Kit has 100W of solar.</p>
              <code>Calculation: <div>{makeTotalBatteryUsage()}Wh calculated battery size</div><div>/ 5 hours of average usable sunshine in most states</div><div>= {makeTotalBatteryUsage() / 5}W</div> </code>
            </div>
          </div>
        </div>
      </div>
    </Zoom>
    }


  </div>
)}

export default App;